entries.example:
Template = GetCommonTemplate("InvoiceKO1");
Sheet = New SpreadsheetDocument();
Sheet.Put(Template.GetArea("Header"));
Sheet.Show("Invoice");

Sheet.Put(Template.GetArea("Header"));
For Each Line In Goods Do
    Sheet.Put(Template.GetArea("Row|Number"));
    Sheet.Join(Template.GetArea("Row|Goods"));
EndDo;

Head = Template.GetArea("Header");
Head.Parameters.Number = Ref.Number;
Head.Parameters.TotalAmount = Format(Total, "NFD=2");
Sheet.Put(Head);

Cell = Sheet.Area(0, 0);          // top-left: zero, not one
Message(Cell.Value);              // read it back
Cell.Value = "Report title";
Cell.BackgroundColour = New Colour(255, 255, 204);

For Each Ref In Documents Do
    If Not First Then
        Sheet.PutHorizontalPageBreak();
    EndIf;
    First = False;
    PrintOne(Sheet, Ref);
EndDo;

Sheet.Put(Template.GetArea("GroupHeader"));
Sheet.BeginRowGroup();
For Each Line In Rows Do
    Sheet.Put(Template.GetArea("Row"));
EndDo;
Sheet.EndRowGroup();

Cell = Sheet.Area(0, 0);
Cell.Value = "Turnover";
Cell.BackgroundColour = New Colour(255, 255, 204);
Cell.Size = New Size(1, 3);   // merged with the two cells to its right

Areas = Template.Areas;
Message(Areas.Count());
Header = Areas.Get("Header");   // Undefined when the template has no such area

entries.syntax_block:
Area.Parameters.<name> = value;
Area.Parameters.Set(name, value);
Value = Area.Parameters.Get(name);

entries.example:
Head = Template.GetArea("Header");
Head.Parameters.Number = Ref.Number;
Head.Parameters.Set("Date", Ref.Date);
Sheet.Put(Head);

Row = Template.GetArea("Row");
Row.Parameters.Fill(New Structure("Goods, Quantity", Line.Goods, Line.Quantity));
Sheet.Put(Row);
